import React, { useEffect, useRef, useState } from 'react';

export default function AdBanner() {
  const [banners, setBanners]   = useState([]);
  const [index, setIndex]       = useState(0);
  const [sliding, setSliding]   = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 560);

  // desktop scroll
  const trackRef = useRef(null);
  const animRef  = useRef(null);
  const posRef   = useRef(0);

  useEffect(() => {
    const handle = () => setIsMobile(window.innerWidth <= 560);
    window.addEventListener('resize', handle);
    return () => window.removeEventListener('resize', handle);
  }, []);

  useEffect(() => {
    fetch('http://localhost:5000/api/banners/current')
      .then(r => r.json())
      .then(data => { if (data.banners?.length) setBanners(data.banners); })
      .catch(() => {});
  }, []);

  // ── Desktop: continuous scroll ──────────────────────────────
  useEffect(() => {
    if (isMobile || !banners.length || !trackRef.current) return;
    const track = trackRef.current;
    const SPEED = 0.7;
    posRef.current = 0;

    const step = () => {
      posRef.current += SPEED;
      const halfWidth = track.scrollWidth / 2;
      if (posRef.current >= halfWidth) posRef.current = 0;
      track.style.transform = `translateX(-${posRef.current}px)`;
      animRef.current = requestAnimationFrame(step);
    };

    animRef.current = requestAnimationFrame(step);
    return () => cancelAnimationFrame(animRef.current);
  }, [banners, isMobile]);

  // ── Mobile: auto-advance every 3s ───────────────────────────
  useEffect(() => {
    if (!isMobile || banners.length <= 1) return;
    const t = setInterval(() => {
      setSliding(true);
      setTimeout(() => {
        setIndex(i => (i + 1) % banners.length);
        setSliding(false);
      }, 500);
    }, 3000);
    return () => clearInterval(t);
  }, [banners, isMobile]);

  if (!banners.length) return null;

  // ── Desktop render ───────────────────────────────────────────
  if (!isMobile) {
    const items = [...banners, ...banners]; // duplicate for seamless loop
    return (
      <div style={desktopWrapper}>
        <div ref={trackRef} style={desktopTrack}>
          {items.map((b, i) => (
            <img key={i} src={b.url} alt="" style={desktopImg} draggable={false} />
          ))}
        </div>
      </div>
    );
  }

  // ── Mobile render ────────────────────────────────────────────
  return (
    <div style={mobileWrapper}>
      {banners.map((b, i) => (
        <img
          key={b.url}
          src={b.url}
          alt=""
          style={{
            ...mobileImg,
            opacity:   i === index ? 1 : 0,
            transform: i === index
              ? (sliding ? 'translateX(-100%)' : 'translateX(0)')
              : 'translateX(100%)',
            transition: 'transform 0.5s ease, opacity 0.5s ease',
          }}
        />
      ))}

      {banners.length > 1 && (
        <div style={dots}>
          {banners.map((_, i) => (
            <div key={i} onClick={() => setIndex(i)} style={{
              width: i === index ? 20 : 7, height: 7, borderRadius: 4,
              background: i === index ? '#f97316' : 'rgba(255,255,255,0.4)',
              cursor: 'pointer', transition: 'width 0.3s, background 0.3s',
            }} />
          ))}
        </div>
      )}
    </div>
  );
}

// ── Desktop styles ─────────────────────────────────────────────
const desktopWrapper = {
  width: '100%',
  height: 180,
  overflow: 'hidden',
  background: '#000',
  borderBottom: '1px solid #1a1a1a',
  position: 'relative',
};

const desktopTrack = {
  display: 'flex',
  alignItems: 'center',
  height: '100%',
  willChange: 'transform',
};

const desktopImg = {
  height: '100%',
  width: 'auto',
  flexShrink: 0,
  objectFit: 'cover',
  display: 'block',
  userSelect: 'none',
  pointerEvents: 'none',
};

// ── Mobile styles ──────────────────────────────────────────────
const mobileWrapper = {
  position: 'relative',
  width: '100%',
  height: 240,
  overflow: 'hidden',
  background: '#000',
  borderBottom: '1px solid #1a1a1a',
};

const mobileImg = {
  position: 'absolute',
  inset: 0,
  width: '100%',
  height: '100%',
  objectFit: 'contain',
  objectPosition: 'center',
  display: 'block',
  userSelect: 'none',
  pointerEvents: 'none',
};

const dots = {
  position: 'absolute',
  bottom: 10,
  left: '50%',
  transform: 'translateX(-50%)',
  display: 'flex',
  gap: 6,
  alignItems: 'center',
};
